with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CCP_80D_PREMIUM as SECTION_80D_ELIGIBLE_PREMIUM
