        , UTGST_AMT as UTGST_AMOUNT
        , TP_TAX_CODE as TP_SCOPE_TAX_CODE
        , BTP_TAX_CODE as BTP_SCOPE_TAX_CODE
        , PARTNER_GSTN as GSTIN_OF_DISTRIBUTION_PARTNER
        , cast(null as varchar) as STAMP_DUTY_CHARGEABLE_INDICATOR
        , cast(null as varchar) as TAX_CODE
        , cast(null as varchar) as TAX_TYPE_1_CODE
        , cast(null as varchar) as TAX_TYPE_2_CODE
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as SECTION_80D_ELIGIBLE_PREMIUM
        , cast(null as varchar) as SECTION_80D_ELIGIBLE_PREMIUM_ON_ENDORSEMENT
        , UTGST_AMT as UTGST_AMOUNT
        , TP_TAX_CODE as TP_SCOPE_TAX_CODE
        , BTP_TAX_CODE as BTP_SCOPE_TAX_CODE
        , PARTNER_GSTN as GSTIN_OF_DISTRIBUTION_PARTNER
        , STAMP_DUTY_CHARGABLE_YN as STAMP_DUTY_CHARGEABLE_INDICATOR
