        , TAX_TYPE1 as TAX_TYPE_1_CODE
        , TAX_TYPE2 as TAX_TYPE_2_CODE
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SECTION_80D_ELIGIBLE_PREMIUM end) as SECTION_80D_ELIGIBLE_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SECTION_80D_ELIGIBLE_PREMIUM_ON_ENDORSEMENT end) as SECTION_80D_ELIGIBLE_PREMIUM_ON_ENDORSEMENT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then UTGST_AMOUNT end) as UTGST_AMOUNT,
