        max(case when SOURCE_RUN = 'opus_health_delta3' then STAMP_DUTY_CHARGEABLE_INDICATOR end) as STAMP_DUTY_CHARGEABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then TAX_CODE end) as TAX_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then TAX_TYPE_1_CODE end) as TAX_TYPE_1_CODE,
